/// Return `N` bytes generated by a SplitMix generator seeded with `seed`.
///
/// The reference implementations suggest to fill the digits of the state with
/// the output of SplitMix, and to set the carry to one.
pub(crate) fn splitmix_bytes<const N: usize>(mut seed: u64) -> [u8; N] {
    let mut out = [0; N];
    for chunk in out.chunks_mut(8) {
        seed = seed.wrapping_add(0x9e3779b97f4a7c15);
        let mut z = seed;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d049bb133111eb);
        z ^= z >> 31;
        chunk.copy_from_slice(&z.to_le_bytes()[..chunk.len()]);
    }
    out
}

/// Return the little-endian bytes of the integer held in `words`.
pub(crate) fn to_bytes<const N: usize, const B: usize>(words: [u64; N]) -> [u8; B] {
    const { assert!(B == 8 * N) };
    let mut out = [0; B];
    for (chunk, w) in out.chunks_exact_mut(8).zip(words) {
        chunk.copy_from_slice(&w.to_le_bytes());
    }
    out
}
